//SOUND_BEGIN
// =========================================================================
// Title: Everything's A Caustic
// Author: Wyatt
// Source: https://www.shadertoy.com/view/WdBGDm
// License: CC BY-NC-SA 3.0 (Shadertoy Default License)
//
// Note: Granular and caustic sound synthesis.
//       Adapted for Desktop GLSL Audio.
// =========================================================================

#define PI2_LOCAL 6.28318530718
#define M_C 261.625565
#define PW 1.05946309436

// Hash 3D per la generazione di numeri casuali (Dave Hoskins)
vec3 hash31(float p) {
   vec3 p3 = fract(vec3(p) * vec3(.1031, .1030, .0973));
   p3 += dot(p3, p3.yzx + 19.19);
   return fract((p3.xxy + p3.yzz) * p3.zyx); 
}

// Funzione generatrice della nota (Sintesi FM + Inviluppo)
float X (
    float time,
    float phase,
    float octave, 
    float note, 
    float attack,
    float sustain,
    float release,
    float nl
) {
    float phi = phase * PI2_LOCAL;
    // Calcolo della frequenza basato sul temperamento equabile
    float w = M_C * PI2_LOCAL * exp2(octave) * pow(PW, note);

    // Inviluppo ADSR semplificato
    float envelope = smoothstep(0., attack, time - phase) * smoothstep(release, 0., time - phase - attack - sustain);

    // Sintesi FM: due oscillatori dove la fase è modulata da un altro coseno
    float wave1 = cos(w * time - phi + 50. * cos(0.001 * nl * w * time));
    float wave2 = cos(0.25 * w * time - phi + 30. * cos(0.002 * nl * w * time));

    return (wave1 + wave2) * envelope;
}

// -------------------------------------------------------------------------
// MAIN SOUND
// -------------------------------------------------------------------------

vec2 mainSound( in int samp, float t ) {
    float a = 0.;
    #define N_VOICES 15.

    // Iterazione per generare polifonia e texture
    for (float i = 0.; i < N_VOICES; i++) {
        float time_idx = 0.;
        float note = 0.;
        float root = 0.;
        float octave = 1.0;
        vec3 h;
        float d = 1.0;

        // Logica temporale per creare ritmi frattali
        time_idx = floor(t);
        h = hash31(time_idx);
        root = floor(h.x * 12.) - 12.;
        h = hash31(time_idx + i);

        // Suddivisione ritmica casuale (stocastica)
        if (h.x > 0.4) {
            d *= 0.5;
            time_idx = floor(t);
            h = hash31(2. * time_idx + i * 100.);
            if (h.x > 0.6) {
                d *= 0.5;
                time_idx = floor(t * 2.) / 2.;
                h = hash31(20. * time_idx + i * 120.);
            }
        }

        // Selezione della nota nella scala
        note = 2. * floor(h.z * 6.) - 4.;

        // Somma delle voci
        a += 0.5 * X(t, time_idx, octave, root + note, 0.01 * d, 0.9 * d, 0.1 * d, 0.2 * h.x);
    }

    // Normalizzazione e output stereo (mono in questo caso, bilanciato su vec2)
    vec2 audio = vec2(a) / N_VOICES;

    // Fade-in iniziale e limiter finale
    return clamp(audio * smoothstep(0.0, 1.0, t), -1.0, 1.0);
}
//SOUND_END

// =========================================================================
// Title: Disco Sun Vortex
// Author: workingclasshacker (@WorkingClassHacker)
// Source: https://www.shadertoy.com/view/7cfGzn
//
// License: SPDX-License-Identifier: CC-BY-NC-SA-4.0
//          https://creativecommons.org/licenses/by-nc-sa/4.0/
//          Copyright (c) 2026 @WorkingClassHacker
//
// Attributions & Credits:
// - Based on "Abstract Shine" by @Frostbyte (Copyright (c) 2026)
// - Continuous cosine palette by Inigo Quilez / IQ (MIT License) 
//   https://www.shadertoy.com/view/ll2GD3
//
// Description:
// Volumetric raymarching shader featuring organic deformation fields, 
// depth-dependent coloration using continuous cosine palettes, and 
// time-gated screen-space shimmer.
// =========================================================================
// Rotation matrix using cosine phase offsets.
// cos(a+33) ≈ -sin(a)
// cos(a+11) ≈  sin(a)
// compact 2D rotation without sin(). 
// Approximates sin within an invisible margin for animated graphics

#define R(a) mat2(cos(a+vec4(0, 33, 11, 0)))

// IQ`s continuous cosine palette (MIT)
// produces smooth, periodic color gradients
// https://www.shadertoy.com/view/ll2GD3

vec3 palette(float i){
    const vec3 a = vec3(0.50, 0.38, 0.26);  // base tone (warm midtone)
    const vec3 b = vec3(0.50, 0.35, 0.25);  // amplitude (vibrance)
    const vec3 c = vec3(1.00);              // frequency (cyclic complexity)
    const vec3 d = vec3(0.00, 0.12, 0.25);  // phase offsets (hue shift)
    return a + b * cos(6.2831853 * (c * i + d));
}

vec3 palette2(float i){
    // Rimosse tutte le "f" finali per compatibilità universale
    const vec3 a = vec3(0.742702, 0.908877, 0.959831);
    const vec3 b = vec3(-0.711000, 0.275000, -0.052000);
    const vec3 c = vec3(1.000000, 1.855000, 1.000000);
    const vec3 d = vec3(0.180000, 0.091000, 0.380000);
    return a + b * cos(6.2831853 * (c * i + d));
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // pixel coordinate
    vec2 u = fragCoord.xy;

    // normalized screen space
    vec2 uv = (u - 0.5*iResolution.xy + 0.5) / iResolution.y;

    // FIX 1: Inizializziamo a zero!
    float i = 0.0;
    float s = 0.0;
    float t = iTime;

    // FIX 2: Inizializziamo p a zero, poi impostiamo la Z
    vec3 p = vec3(0.0, 0.0, t);

    // ray direction
    vec3 d = normalize(vec3(
        2.0 * u - iResolution.xy,
        iResolution.y
    ));

    // FIX 3: Inizializziamo il colore a nero prima di sommarci la luce
    fragColor = vec4(0.0);

    // raymarch loop (ciclo pulito e standard)
    for (i = 0.0; i < 20.0; i++)
    {
        // depth-dependent rotation
        p.xy *= R(-p.z * 0.01 - iTime * 0.05);

        // base step size
        s = 0.6;

        // cylindrical confinement
        s = max(s, 4.0 * (-length(p.xy) + 10.0));

        // organic deformation field
        s += abs(
            p.y * 0.004 +                
            sin(t - p.x * 0.5) * 0.9 +  
            1.0                          
        );

        // march ray forward
        p += d * s;

        // volumetric glow accumulation
        fragColor += 1.0 / (s * 0.2);
    }

    // apply palette 
    fragColor *= vec4(palette(length(p)/(abs(sin(iTime*0.02)*50.)+6.0)), 1.0);

    // time-gated screen-space shimmer 
    fragColor -= 20.0 *
        smoothstep(
            .001,
            abs(sin(iTime*5.0)), 
            .7 - length(sin(uv*200.0)/1.5)-abs(uv.y)+.2   
        );

    // brightness normalization
    fragColor /= 0.5e2;

    // radial gradient
    float l = length(uv);

    // vignette
    fragColor *= 1.2-l;

    // center glow
    fragColor = mix(fragColor, palette(l-.23).rgbr, 1.0-smoothstep(.01,.95,l));

    // soft highlight compression
    fragColor = tanh(fragColor+fragColor);
}
